#!/usr/bin/env node
// Pre-push self-healing (ADR-202). pre-commit already keeps derived files
// current; this is the safety net for a tree that still arrives stale (an
// older clone, a rebase, an amended commit). Where the fix is deterministic it
// is made and committed as its own commit THROUGH the normal hooks (never a
// bypass), then the push stops once with one line: git cannot add a commit to
// a push that already started, so the developer re-runs `git push`.
//
//   generated knowledge  -> `chore(knowledge): refresh generated files`
//   dependency advisory  -> `chore(deps): patch production dependency advisories`
//   QA evidence missing  -> scaffold ONLY the skeleton; never fill it (rules/60)
//
// Called by tools/gates/pre-push.mjs after the working tree is parked.
import { execFileSync, spawnSync } from 'node:child_process';
import { existsSync } from 'node:fs';

import { git, gitLines, resolveCommit, ZERO_SHA } from '../lib/git.mjs';
import { listFragmentDocs } from '../knowledge/count-fragments.mjs';

function node(script, args, options = {}) {
  return spawnSync(process.execPath, [script, ...args], { encoding: 'utf8', ...options });
}

/** Paths a regeneration may legitimately change. */
export function isDerivedPath(rel, fragmentDocs = new Set()) {
  return (
    rel.startsWith('.ai/') ||
    rel === 'AGENTS.md' ||
    rel.endsWith('/AGENTS.md') ||
    rel === 'docs/features/ai-native-engineering-os/inventory.snapshot.json' ||
    fragmentDocs.has(rel)
  );
}

/** Commit what is staged, through the hooks, with a valid conventional message and Docs trailer. */
function commitThroughHooks(subject, docsTrailer) {
  execFileSync('git', ['commit', '-m', subject, '-m', `Docs: ${docsTrailer}`], {
    stdio: 'inherit',
  });
  return git(['rev-parse', '--short', 'HEAD']);
}

function dirtyPaths() {
  return gitLines(['status', '--porcelain', '--untracked-files=all']).map((line) =>
    line.slice(3).replace(/^"|"$/gu, ''),
  );
}

/**
 * Regenerate the knowledge layer; when that changes only derived files, commit
 * them. Returns the new commit's short sha, or null when nothing was stale.
 */
export function healGenerated() {
  if (node('tools/knowledge/build.mjs', ['--check'], { stdio: 'ignore' }).status === 0) return null;
  const built = node('tools/knowledge/build.mjs', [], { stdio: 'inherit' });
  if (built.status !== 0)
    throw new Error('knowledge:build failed while healing the generated files');
  node('tools/audit/index.mjs', [], { stdio: 'ignore' });
  const fragmentDocs = new Set(listFragmentDocs());
  const dirty = dirtyPaths();
  const foreign = dirty.filter((rel) => !isDerivedPath(rel, fragmentDocs));
  if (foreign.length > 0) {
    throw new Error(
      `regeneration touched non-derived path(s): ${foreign.slice(0, 5).join(', ')} — refusing to commit them`,
    );
  }
  if (dirty.length === 0) return null;
  git(['add', '--', ...dirty]);
  return commitThroughHooks(
    'chore(knowledge): refresh generated files',
    'none — derived files regenerated by tools/knowledge/build.mjs, no hand-written doc changed',
  );
}

/** Patch a new production advisory; commit the manifest + lockfile when it changed them. */
export function healDependencies() {
  const before = gitLines(['status', '--porcelain', '--', 'package.json', 'package-lock.json']);
  if (before.length > 0) return null; // a human edit is in flight; pre-commit reports it
  const result = node('tools/security/audit-fix.mjs', ['--hook'], { stdio: 'inherit' });
  if (result.status !== 0) return null;
  const changed = gitLines(['status', '--porcelain', '--', 'package.json', 'package-lock.json']);
  if (changed.length === 0) return null;
  git(['add', '--', 'package.json', 'package-lock.json']);
  return commitThroughHooks(
    'chore(deps): patch production dependency advisories',
    'none — dependency pin applied by tools/security/audit-fix.mjs, no doc describes this version',
  );
}

/** `<from>..<to>` for each pushed ref; a new branch compares against the default base. */
export function pushRanges(refs, base) {
  return refs.map(({ localSha, remoteSha }) => {
    const from =
      remoteSha && remoteSha !== ZERO_SHA && resolveCommit(remoteSha) !== null ? remoteSha : base;
    return `${from}..${localSha}`;
  });
}

/**
 * The QA-evidence gate is judgment (rules/60), so it is only SCAFFOLDED here:
 * when a feat/fix/perf range owes a record and none exists, a skeleton with
 * every lane unfilled is written and the push stops with ONE message naming it.
 * Returns null when nothing is owed or a record exists, else the message.
 */
export function qaEvidenceProblem(ranges) {
  for (const range of ranges) {
    const check = node('tools/qa/evidence.mjs', ['check', '--range', range]);
    if (check.status === 0) continue;
    const output = `${check.stdout ?? ''}${check.stderr ?? ''}`;
    if (!/MISSING/u.test(output)) {
      return `QA evidence is invalid for ${range}. Fix the lines listed below, then push again.\n${output.trim()}`;
    }
    const first =
      /-\s+[0-9a-f]{7,}\s+(?:\w+)(?:\([^)]*\))?!?:\s*(.+)$/mu.exec(output)?.[1] ?? 'change';
    const slug =
      first
        .toLowerCase()
        .replace(/[^a-z0-9]+/gu, '-')
        .replace(/^-|-$/gu, '')
        .slice(0, 40) || 'change';
    const made = node('tools/qa/evidence.mjs', ['new', slug]);
    const file = /created (docs\/qa-evidence\/\S+\.md)/u.exec(made.stdout ?? '')?.[1];
    const where = file && existsSync(file) ? file : 'docs/qa-evidence/<date>-<slug>.md';
    return (
      `QA evidence is owed for ${range} (a feat/fix/perf product commit has no record). ` +
      `Skeleton scaffolded at ${where}: replace every lane's placeholder with PASS plus the real evidence ` +
      `(or NOT_APPLICABLE with a reason), set Verdict, commit it, push again. Nothing was filled for you (rules/60).`
    );
  }
  return null;
}
